def find_refund_pair(amounts: list[int]) -> tuple[int, int] | None:
    first_seen: dict[int, int] = {}
    for j, amount in enumerate(amounts):
        i = first_seen.get(-amount)
        if i is not None:
            return (i, j)
        first_seen.setdefault(amount, j)
    return None
